// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwnerCandidate, address newOwner) public {
        vm.assume(newOwner != address(0));

        address ownerBefore = c.owner();

        bool ok;
        vm.prank(currentOwnerCandidate);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue( (currentOwnerCandidate == ownerBefore) == ok );
    }
}
